def transform(grid):
    # For each outlined rectangle, fill its interior based on shape parity:
    # odd-by-odd interior -> 7; otherwise -> 2.
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(x==v for row in grid for x in row))
    for color in set(v for row in grid for v in row)-{bg}:
        for r0 in range(h):
            for r1 in range(r0+2,h):
                for c0 in range(w):
                    for c1 in range(c0+2,w):
                        if all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1)):
                            inside=[grid[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
                            if inside and all(v==bg for v in inside):
                                fill=7 if ((r1-r0-1)*(c1-c0-1)) % 2 == 1 else 2
                                for r in range(r0+1,r1):
                                    for c in range(c0+1,c1): out[r][c]=fill
    return out
def transform(grid):
    h,w=len(grid),len(grid[0])
    # Identify grid background and full-width separators.
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    hdivs=[r for r,row in enumerate(grid) if len(set(row))==1 and row[0]!=bg]
    if hdivs:
        divcolor=grid[hdivs[0]][0]
        divs=[r for r in hdivs if grid[r][0]==divcolor]
        bounds=[-1]+divs+[h]
        # Choose populated region as motif and copy it into all other bands;
        # repeat the motif cyclically when band heights differ.
        bands=[(bounds[i]+1,bounds[i+1]) for i in range(len(bounds)-1)]
        src=max(bands,key=lambda ab:sum(v!=bg and v!=divcolor for row in grid[ab[0]:ab[1]] for v in row))
        motif=grid[src[0]:src[1]]
        out=[row[:] for row in grid]
        for a,b in bands:
            if (a,b)==src or not motif: continue
            for r in range(a,b): out[r]=motif[(r-a)%len(motif)][:]
        return out
    # Full-height separator columns define vertical repeated panels.
    vdivs=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1 and grid[0][c]!=bg]
    if vdivs:
        divcolor=grid[0][vdivs[0]]
        divs=[c for c in vdivs if grid[0][c]==divcolor]
        bounds=[-1]+divs+[w]
        panels=[(bounds[i]+1,bounds[i+1]) for i in range(len(bounds)-1)]
        src=max(panels,key=lambda ab:sum(v!=bg and v!=divcolor for row in grid for v in row[ab[0]:ab[1]]))
        out=[row[:] for row in grid]
        for a,b in panels:
            if (a,b)==src: continue
            for r in range(h):
                for c in range(a,b): out[r][c]=grid[r][src[0]+(c-a)%(src[1]-src[0])]
        return out
    return [row[:] for row in grid]
